// Simple Express-path to RegExp converter that handles `:param` segments.
function pathToRegex(path: string): { re: RegExp; paramNames: string[] } {
  const paramNames: string[] = [];
  const pattern = path
    .replace(/[$()*+.?[\\\]^{|}]/g, "\\$&") // escape regex metacharacters except :
    .replace(/:([a-zA-Z_][a-zA-Z0-9_]*)/g, (_match, name: string) => {
      paramNames.push(name);
      return "([^/]+)";
    });
  return { re: new RegExp(`^${pattern}$`), paramNames };
}

// Pre-compile path matchers for each route at app startup.
// These are recomputed whenever the route cache is rebuilt.
let compiledRoutes: Array<{
  route: RouteDefinition;
  re: RegExp;
  paramNames: string[];
}> | null = null;

function getCompiledRoutes(env: Env) {
  const cache = getRouteCache(env);
  if (!compiledRoutes) {
    compiledRoutes = cache.routes.map((route) => ({
      route,
      ...pathToRegex(route.path),
    }));
  }
  return { compiled: compiledRoutes, db: cache.db, storage: cache.storage };
}
